pub fn parse_iso_duration(s: &str) -> Option<u64> {
    if s.is_empty() || !s.starts_with('P') {
        return None;
    }

    let mut chars = s.chars().peekable();
    chars.next(); // consume 'P'

    let mut total_seconds: u64 = 0;
    let mut in_time_part = false;

    while let Some(&c) = chars.peek() {
        if c == 'T' {
            in_time_part = true;
            chars.next();
            continue;
        }

        // Parse number
        let mut num_str = String::new();
        while let Some(&c) = chars.peek() {
            if c.is_ascii_digit() {
                num_str.push(c);
                chars.next();
            } else {
                break;
            }
        }

        if num_str.is_empty() {
            return None;
        }

        let value: u64 = num_str.parse().ok()?;

        // Get the unit character
        let unit = chars.next()?;

        match (in_time_part, unit) {
            (false, 'Y') => total_seconds += value * 31536000, // 365 days
            (false, 'M') => total_seconds += value * 2592000,  // 30 days
            (false, 'W') => total_seconds += value * 604800,   // 7 days
            (false, 'D') => total_seconds += value * 86400,    // 1 day
            (true, 'H') => total_seconds += value * 3600,      // 1 hour
            (true, 'M') => total_seconds += value * 60,        // 1 minute
            (true, 'S') => total_seconds += value,             // 1 second
            _ => return None,
        }
    }

    Some(total_seconds)
}
