from collections import Counter


def top_n(path: str, n: int) -> list[tuple[str, int]]:
    counter = Counter()
    with open(path, 'r') as f:
        for line in f:
            # Extract IP address from the log line.
            # Common log formats have the IP at the beginning of the line,
            # followed by a space or other delimiter.
            # We'll try to extract the first token that looks like an IPv4 address.
            parts = line.split()
            if not parts:
                continue
            ip = None
            for part in parts:
                # Check if the part looks like an IPv4 address
                octets = part.split('.')
                if len(octets) == 4:
                    try:
                        if all(0 <= int(o) <= 255 for o in octets):
                            ip = part
                            break
                    except ValueError:
                        continue
            if ip is not None:
                counter[ip] += 1

    # Sort by frequency descending, then alphabetically ascending
    sorted_items = sorted(counter.items(), key=lambda x: (-x[1], x[0]))
    return sorted_items[:n]
