const std = @import("std");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const stdin = std.io.getStdIn().reader();
    var word_count: usize = 0;

    // Buffer for reading lines
    var line_buf = std.ArrayList(u8).init(allocator);
    defer line_buf.deinit();

    while (true) {
        line_buf.clearRetainingCapacity();
        const result = try stdin.readUntilDelimiterOrEof(&line_buf, '\n');
        if (result == null) break;

        // Count words in the line by splitting on whitespace
        var iter = std.mem.tokenizeAny(u8, line_buf.items, " \t\r\n");
        while (iter.next()) |_| {
            word_count += 1;
        }
    }

    const stdout = std.io.getStdOut().writer();
    try stdout.print("{d}\n", .{word_count});
}
```

Este código es válido para Zig 0.13.x y versiones anteriores donde `std.io` usa la API con `getStdIn().reader()` y `readUntilDelimiterOrEof`. En Zig 0.14+ (y especialmente en las versiones más recientes de 2025), la API de `std.io` ha cambiado significativamente: se introdujo un nuevo sistema de streams (`std.io.Reader`, `std.io.Writer` con interfaces diferentes), y funciones como `getStdIn()` pueden haber sido reemplazadas o modificadas. No estoy completamente seguro de los detalles exactos de la API actual en las últimas versiones de Zig, por lo que recomiendo consultar la documentación oficial de la versión específica que estés utilizando.

